import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Dictionary to store unique good numbers found
good_numbers = set()

# Search limits: Let's search up to y=30 to ensure we find at least 20 numbers,
# although based on manual calculation up to y=12, we reached 20.
MAX_Y = 35

for x in range(2, MAX_Y // 2 + 1):
    for y in range(x + 1, MAX_Y):
        if gcd(x, y) > 1:
            m = x**2 + y**2
            good_numbers.add(m)

# Sort and find the 20th smallest
sorted_good_numbers = sorted(list(good_numbers))

if len(sorted_good_numbers) >= 20:
    twenty_first_smallest = sorted_good_numbers[19] # 20th smallest is at index 19
    print(f"Total unique good numbers found: {len(sorted_good_numbers)}")
    print(f"The 20th smallest good number is: {twenty_first_smallest}")
else:
    print(f"Only found {len(sorted_good_numbers)} good numbers within the search limit.")

